with open('contacts.csv', newline='') as f:
    rows = list(csv.DictReader(f))

best = {}
for r in rows:
    email = r['email'].strip().lower()
    created = r['created'].strip()
    # Strict '<' keeps the first-appearing row on a tie.
    if email not in best or created < best[email]['created']:
        best[email] = {'name': r['name'], 'email': email, 'created': created}

out = sorted(best.values(), key=lambda r: (r['created'], r['email']))

with open('clean.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=['name', 'email', 'created'], lineterminator='\n')
    w.writeheader()
    w.writerows(out)
